def bf(planet1, planet2):
  planets = ["Mercury", "Venus", "Earth", "Mars", "Jupiter", "Saturn", "Uranus"]
  if (planet1 not in planets) or (planet2 not in planets):
    return []
  else:
    q = deque()
    q.append((planet1, 0))
    q.append((planet2, 0))
    result = []
    while len(q) > 0:
        current_planet, distance = q.popleft()
        for i in range(distance + 1):
            new_planet = current_planet + str(i)
            if new_planet in planets:
                q.append((new_planet, distance + 1))
                result.append(new_planet)
    return tuple(result)

